def infer_types(headers, rows):
    types=[]
    for i,h in enumerate(headers):
        # find first non-null value
        val=None
        for r in rows:
            if r[i] is not None:
                val=r[i]
                break
        if val is None:
            types.append("int32")
        elif isinstance(val, int):
            # check if within 32?
            if -2147483648 <= val <= 2147483647:
                types.append("int32")
            else:
                types.append("int64")
        elif isinstance(val, float):
            if math.isinf(val) or math.isnan(val):
                types.append("double")
            else:
                # check decimal representation
                # for 1.5 -> decimal(2,1), 3.14 -> decimal(3,2)
                s=str(val)
                if "." in s:
                    int_part, dec_part = s.split(".",1)
                    # remove sign
                    int_part=int_part.lstrip("-")
                    prec=len(int_part)+len(dec_part)
                    scale=len(dec_part)
                    types.append(f"decimal({prec},{scale})")
                else:
                    types.append("double")
        elif isinstance(val, bytes):
            types.append("blob")
        elif isinstance(val, bool):
            types.append("boolean")
        else:
            types.append("varchar")
    return types

def render_duckbox(headers, types, rows, nullvalue):
    cols=len(headers)
    if cols==0: return ""
    widths=[]
    for i in range(cols):
        max_w=len(headers[i])
        max_w=max(max_w, len(types[i]))
        for r in rows:
            v=r[i]
            if v is None: s=nullvalue
            elif isinstance(v,float) and (math.isinf(v) or math.isnan(v)):
                s="inf" if math.isinf(v) and v>0 else "-inf" if math.isinf(v) else "nan"
            else: s=str(v)
            max_w=max(max_w, len(s))
        widths.append(max_w+2)
    def top():
        s="┌"
        for i,w in enumerate(widths):
            s+="─"*w
            if i<len(widths)-1: s+="┬"
        s+="┐\n"
        return s
    def mid():
        s="├"
        for i,w in enumerate(widths):
            s+="─"*w
            if i<len(widths)-1: s+="┼"
        s+="┤\n"
        return s
    def bottom():
        s="└"
        for i,w in enumerate(widths):
            s+="─"*w
            if i<len(widths)-1: s+="┴"
        s+="┘\n"
        return s
    out=""
    out+=top()
    # header centered
    s="│"
    for i,w in enumerate(widths):
        cell=headers[i]
        inner=w
        pad=inner-len(cell)
        left=pad//2
        right=pad-left
        s+=" "*left+cell+" "*right+"│"
    out+=s+"\n"
    # types centered
    s="│"
    for i,w in enumerate(widths):
        cell=types[i]
        inner=w
        pad=inner-len(cell)
        left=pad//2
        right=pad-left
        s+=" "*left+cell+" "*right+"│"
    out+=s+"\n"
    out+=mid()
    for r in rows:
        s="│"
        for i,w in enumerate(widths):
            v=r[i]
            if v is None: cell=nullvalue
            elif isinstance(v,float) and (math.isinf(v) or math.isnan(v)):
                cell="inf" if math.isinf(v) and v>0 else "-inf" if math.isinf(v) else "nan"
            else: cell=str(v)
            inner=w
            is_numeric=types[i].startswith("int") or types[i].startswith("decimal") or types[i]=="double"
            if types[i]=="boolean": is_numeric=False
            if is_numeric:
                s+=" "+cell.rjust(inner-2)+" "+"│"
            else:
                s+=" "+cell.ljust(inner-2)+" "+"│"
        out+=s+"\n"
    out+=bottom()
    return out

def render_box(headers, rows, nullvalue):
    cols=len(headers)
