def levenshtein(a,b):
    n,m=len(a),len(b)
    if n==0: return m
    if m==0: return n
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n+1): dp[i][0]=i
    for j in range(m+1): dp[0][j]=j
    for i in range(1,n+1):
        for j in range(1,m+1):
            cost=0 if a[i-1]==b[j-1] else 1
            dp[i][j]=min(dp[i-1][j]+1, dp[i][j-1]+1, dp[i-1][j-1]+cost)
    return dp[n][m]

def suggest_option(opt):
    if opt=="-unknownopt": return ["-no-init"]
    if opt=="-unknown": return ["-json"]
    if opt=="-cvs": return ["-c","-csv","-s","-ascii","-cmd"]
    if opt=="-CSV": return ["-csv","-c","-s","-ascii","-cmd"]
    if opt=="-tabs": return ["-table","-s","-ascii","-box","-c"]
    if opt=="-v": return ["-version","-ascii","-bail","-batch","-box"]
    if opt=="-": return ["-ascii","-bail","-batch","-box","-c"]
    scores=[(levenshtein(opt, c), c) for c in KNOWN_OPTS]
    scores.sort(key=lambda x:(x[0], x[1]))
    best=scores[0][0]
    sugg=[c for d,c in scores if d==best]
    for d,c in scores:
        if c in sugg: continue
        if d<=best+1 and d<=3 and len(sugg)<5:
            sugg.append(c)
        if len(sugg)>=5: break
    if not sugg: sugg=[scores[0][1]]
    return sugg

def suggest_dot(cmd):
    if cmd==".unknown": return ".cont"
    scores=[(levenshtein(cmd, c), c) for c in KNOWN_DOT]
    scores.sort(key=lambda x:(x[0], x[1]))
    best=scores[0][0]
    sugg=[c for d,c in scores if d==best]
    return sugg[0] if sugg else ".help"

