def infer_types(headers, rows):
    types=[]
    for i,h in enumerate(headers):
        # find first non-null value
        val=None
        for r in rows:
            if r[i] is not None:
                val=r[i]
                break
        if val is None:
            types.append("int32")
        elif isinstance(val, int):
            # check if within 32?
            if -2147483648 <= val <= 2147483647:
                types.append("int32")
            else:
                types.append("int64")
        elif isinstance(val, float):
            if math.isinf(val) or math.isnan(val):
                types.append("double")
            else:
                # check decimal representation
                # for 1.5 -> decimal(2,1), 3.14 -> decimal(3,2)
                s=str(val)
                if "." in s:
                    int_part, dec_part = s.split(".",1)
                    # remove sign
                    int_part=int_part.lstrip("-")
                    prec=len(int_part)+len(dec_part)
                    scale=len(dec_part)
                    types.append(f"decimal({prec},{scale})")
                else:
                    types.append("double")
        elif isinstance(val, bytes):
            types.append("blob")
        elif isinstance(val, bool):
            types.append("boolean")
        else:
            types.append("varchar")
    return types

def render_duckbox(headers, types, rows, nullvalue):
